"use client";

import Link from "next/link";
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { IdempotencyAttempt } from "@/lib/idempotency-attempt";
import { collectionSpecimenAttempt } from "./collection-specimen-attempt";
import { submitCollectionJob } from "./collection-job-create";
import { collectionOperationsQuery } from "@/lib/collection-operations-query";
import { resolveAuthorizedCentreFilter } from "@/lib/authorized-centre-selection";
import { localCalendarDate } from "@/server/collection-schedule-policy";
import type { PermissionGrant } from "@/server/permissions";
import { mayAuthorizeRecollectionAtCentre, mayCreateCollectionJobAtCentre, mayDispatchSamplesAtCentre, mayManageProceduresAtCentre, mayManageSampleExceptionsAtCentre, mayReceiveSamplesAtCentre, mayRecordVisitAtCentre, mayCollectSampleAtCentre, mayVerifyExternalReceiptAtCentre } from "@/lib/sample-operations-permissions";

type ApiResult = { response: Response; body: Record<string, unknown> };
type Job = { id: string; jobNumber: string; centreId: string; centreTimeZone?: string; appointmentId: string; orderId: string; patientId: string; patientName?: string; patientLastName?: string; visitType?: string; homeCollectionAddress?: Record<string,string> | null; homeCollectionWindow?: string | null; status: string; assignedStaffId: string | null; scheduledStart: string; scheduledEnd: string; versionNumber: number };
type Specimen = { id: string; centreId: string; jobId: string; orderId: string; patientId: string; patientName?: string; patientLastName?: string; specimenNumber: string; specimenType: string; requirementReference: string; identityCheckConfirmed?: boolean; status: string; collectedAt: string; receivedAt: string | null; versionNumber: number; receivingSubmissionRequired?: boolean; handoverSubmitted?: boolean; canSubmitHandover?: boolean };
type Procedure = { id: string; centreId: string; operation: string; reference: string };
type Eligible = { appointmentId: string; appointmentNumber: string; orderId: string; orderNumber: string; centreId: string; patientId: string; patientName: string; patientLastName: string; visitType: string; scheduledAt: string };
type Centre = { id: string; name: string; code: string };
type Assignee = { id: string; displayName: string; staffCode: string };
type Batch = { id: string; centreId: string; batchNumber: string; status: string; carrierReference: string | null; externalLabReference: string | null; versionNumber: number };

async function request(url: string, init?: RequestInit): Promise<ApiResult> {
  const response = await fetch(url, { cache: "no-store", ...init });
  let body: Record<string, unknown> = {};
  try { body = await response.json() as Record<string, unknown>; } catch { /* empty service response */ }
  return { response, body };
}

function message(body: Record<string, unknown>, fallback: string) { return typeof body.error === "string" ? body.error.replaceAll("_", " ") : fallback; }
function formatJobTime(job: Job) { return new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "short", ...(job.centreTimeZone ? { timeZone: job.centreTimeZone, timeZoneName: "short" as const } : {}) }).format(new Date(job.scheduledStart)); }
function TableMessage({ value }: { value: string }) { return <p role="status" aria-live="polite">{value}</p>; }
function FormResult({ value }: { value: string }) { return <p className="form-message" role="status" aria-live="polite">{value}</p>; }

export function CollectionOperations({ grants = [], showDailySchedule = false, showScheduleDateFilter = false, initialCentreId }: { grants?: readonly PermissionGrant[]; showDailySchedule?: boolean; showScheduleDateFilter?: boolean; initialCentreId?: string }) {
  const [jobs, setJobs] = useState<Job[]>([]); const [eligible, setEligible] = useState<Eligible[]>([]); const [centres, setCentres] = useState<Centre[]>([]); const [procedures, setProcedures] = useState<Procedure[]>([]); const [state, setState] = useState("Loading collection operations…"); const [busy, setBusy] = useState(""); const [result, setResult] = useState(""); const [page, setPage] = useState(1); const [hasMore, setHasMore] = useState(false); const [centreId, setCentreId] = useState(initialCentreId ?? ""); const [summary, setSummary] = useState<{ total: number; byStatus: Record<string, number> }>({ total: 0, byStatus: {} });
  const initialCentreResolved = useRef(false);
  const showDateFilter = showDailySchedule || showScheduleDateFilter;
  const [scheduleDate, setScheduleDate] = useState(() => showDailySchedule ? localCalendarDate(new Date()) : "");
  const createJobAttempts = useRef(new Map<string, IdempotencyAttempt>());
  const refresh = useCallback(async () => {
    setJobs([]); setEligible([]); setSummary({ total: 0, byStatus: {} }); setHasMore(false);
    if (showDailySchedule && !scheduleDate) { setState("Choose a schedule date to view assigned collections."); return; }
    setState("Loading collection operations…");
    if (showDailySchedule && !scheduleDate) return;
    try {
      const params = collectionOperationsQuery({ page, pageSize: 50, centreId, scheduleDate, includeScheduleDate: showDateFilter });
      const [j, e, c, p] = await Promise.all([request(`/api/collections?${params}`), request("/api/collections/eligible"), request("/api/collections/centres"), request("/api/samples/procedures")]);
      const authorizedCentres = c.response.ok ? (c.body.centres ?? []) as Centre[] : []; setCentres(authorizedCentres); if (initialCentreId && !initialCentreResolved.current) { setCentreId(resolveAuthorizedCentreFilter(authorizedCentres, initialCentreId)); initialCentreResolved.current = true; }
      if (!j.response.ok) { setState(message(j.body, "Collection service unavailable.")); return; }
      setJobs((j.body.jobs ?? []) as Job[]); setHasMore(j.body.hasMore === true); setSummary((j.body.summary ?? { total: 0, byStatus: {} }) as { total: number; byStatus: Record<string, number> }); setEligible(e.response.ok ? (e.body.eligible ?? []) as Eligible[] : []); setProcedures(p.response.ok ? (p.body.procedures ?? []) as Procedure[] : []); setState("");
    } catch { setState("Collection service unavailable. Check the local database connection."); }
  }, [centreId, initialCentreId, page, scheduleDate, showDailySchedule, showDateFilter]);
  useEffect(() => { void Promise.resolve().then(refresh); }, [refresh]);
  async function createJob(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault(); const formElement = event.currentTarget; const form = new FormData(formElement); const selected = eligible.find((row) => row.orderId === String(form.get("orderId"))); if (!selected || !mayCreateCollectionJobAtCentre(grants, selected.centreId)) return;
    setBusy("create"); setResult("");
    const attempt = createJobAttempts.current.get(selected.orderId) ?? new IdempotencyAttempt(`rudra:collection-job:${selected.orderId}`);
    createJobAttempts.current.set(selected.orderId, attempt);
    const result = await submitCollectionJob({ appointmentId: selected.appointmentId, orderId: selected.orderId }, attempt);
    if (result.kind === "saved") {
      createJobAttempts.current.delete(selected.orderId);
      setResult(result.replayed ? "This confirmed booking already has a collection job." : `Collection job ${String((result.body.job as Record<string, unknown>)?.jobNumber ?? "created")} is ready.`);
      formElement.reset();
      await refresh();
    } else if (result.kind === "rejected") {
      if (result.status < 500) createJobAttempts.current.delete(selected.orderId);
      setResult(`Could not create job: ${message(result.body, "service unavailable")}.`);
    } else {
      setResult("The result could not be confirmed. Retry the same booking to safely check whether its collection job was saved.");
    }
    setBusy("");
  }
  const byStatus = useMemo(() => summary.byStatus, [summary]);
  return <>
    <section className="sample-stat-grid">{[["Total jobs", summary.total], ["Unassigned", byStatus.PENDING_ASSIGNMENT ?? 0], ["In progress", byStatus.IN_PROGRESS ?? 0], ["Unsuccessful", byStatus.UNSUCCESSFUL ?? 0]].map(([label, count]) => <article className="admin-card" key={String(label)}><span>{label}</span><strong>{count}</strong></article>)}</section>
     {grants.some((grant) => grant.key === "collections.assign") ? <section className="admin-card"><h2>Start from a confirmed appointment and order</h2><p>A job is created only when its appointment and diagnostic order are confirmed and linked to the same patient and centre.</p>{eligible.some((row) => (!centreId || row.centreId === centreId) && mayCreateCollectionJobAtCentre(grants, row.centreId)) ? <form className="admin-form sample-form" onSubmit={(event) => void createJob(event)}><label>Eligible booking<select name="orderId" required defaultValue=""><option value="" disabled>Select confirmed booking</option>{eligible.filter((row) => (!centreId || row.centreId === centreId) && mayCreateCollectionJobAtCentre(grants, row.centreId)).map((row) => <option key={row.orderId} value={row.orderId}>{row.appointmentNumber} · {row.orderNumber} · {row.patientName} {row.patientLastName} · {row.visitType}</option>)}</select></label><button className="button button-primary" disabled={busy === "create"}>{busy === "create" ? "Creating…" : "Create collection job"}</button><FormResult value={result} /></form> : <TableMessage value={state || "No eligible confirmed appointment/order pairs are waiting in the selected centre where you can assign collection jobs."} />}</section> : null}
      <section className="admin-card"><h2>{showDailySchedule ? "My daily collection schedule" : "Collection operations"}</h2>{!showDailySchedule ? <label>Centre<select value={centreId} onChange={(event) => { setCentreId(event.target.value); setPage(1); }}><option value="">All authorized centres</option>{centres.map((centre) => <option key={centre.id} value={centre.id}>{centre.name} ({centre.code})</option>)}</select></label> : null}{showDateFilter ? <div className="admin-form sample-form"><label htmlFor="collection-schedule-date">{showDailySchedule ? "Schedule date" : "Filter schedule date"} (interpreted in each centre’s timezone)</label><div className="task-actions"><input id="collection-schedule-date" type="date" value={scheduleDate} onChange={(event) => { setScheduleDate(event.target.value); setPage(1); }} />{!showDailySchedule && scheduleDate && <button type="button" className="button button-secondary" onClick={() => { setScheduleDate(""); setPage(1); }}>Clear date</button>}</div></div> : null}{state ? <TableMessage value={state} /> : jobs.length ? <><div className="table-scroll"><table className="admin-table"><thead><tr><th>Job</th><th>Patient</th><th>Visit</th><th>Scheduled (centre time)</th><th>Status</th><th>Actions</th></tr></thead><tbody>{jobs.map((job) => <tr key={job.id}><td>{job.jobNumber}</td><td>{job.patientName} {job.patientLastName}</td><td>{job.visitType}</td><td>{formatJobTime(job)}</td><td>{job.status.replaceAll("_", " ")}</td><td><Link href={`/collections/${job.id}`}>Open workflow</Link></td></tr>)}</tbody></table></div><div className="action-row"><button className="button button-secondary" disabled={page <= 1} onClick={() => setPage((current) => current - 1)}>Previous page</button><span>Page {page}</span><button className="button button-secondary" disabled={!hasMore} onClick={() => setPage((current) => current + 1)}>Next page</button></div></> : <TableMessage value={showDailySchedule ? "No assigned collection jobs for this centre-local date." : "No collection jobs in the selected schedule."} />}</section>
    {centres.some((centre) => mayManageProceduresAtCentre(grants, centre.id)) ? <ProcedureAdmin centres={centres.filter((centre) => mayManageProceduresAtCentre(grants, centre.id))} procedures={procedures.filter((procedure) => mayManageProceduresAtCentre(grants, procedure.centreId))} onSaved={refresh} /> : null}
  </>;
}

export function ProcedureReferenceManager() {
  const [centres,setCentres]=useState<Centre[]>([]); const [procedures,setProcedures]=useState<Procedure[]>([]); const [state,setState]=useState("Loading reference configuration…");
  const refresh=useCallback(async()=>{try{const [c,p]=await Promise.all([request("/api/collections/centres"),request("/api/samples/procedures")]);if(!c.response.ok){setState(message(c.body,"Centre service unavailable."));return;}setCentres((c.body.centres??[]) as Centre[]);setProcedures(p.response.ok?(p.body.procedures??[]) as Procedure[]:[]);setState("");}catch{setState("Reference service unavailable.");}},[]);useEffect(()=>{void Promise.resolve().then(refresh);},[refresh]);
  return <>{state?<section className="admin-card"><TableMessage value={state}/></section>:null}<ProcedureAdmin centres={centres} procedures={procedures} onSaved={refresh}/></>;
}

function ProcedureAdmin({ centres, procedures, onSaved }: { centres: Centre[]; procedures: Procedure[]; onSaved: () => Promise<void> }) {
  const [state, setState] = useState(""); const [busy, setBusy] = useState(false);
  async function submit(event: React.FormEvent<HTMLFormElement>) { event.preventDefault(); const formElement = event.currentTarget; setBusy(true); setState(""); const data = Object.fromEntries(new FormData(event.currentTarget)); const { response, body } = await request("/api/samples/procedures", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(data) }); setState(response.ok ? "Approved procedure reference recorded." : `Could not save: ${message(body, "service unavailable")}.`); setBusy(false); if (response.ok) { formElement.reset(); await onSaved(); } }
  return <section className="admin-card"><h2>Approved operating procedure references</h2><p>Only record references to a separately approved procedure. This application does not provide clinical handling instructions, specimen requirements, stability limits or transport conditions. Actions stay blocked until the relevant reference is recorded.</p><div className="sample-chip-list">{procedures.map((item) => <span className="sample-chip" key={item.id}>{item.operation} · {item.reference}</span>)}</div>{centres.length ? <form className="admin-form sample-form" onSubmit={(event) => void submit(event)}><label>Centre<select name="centreId" required defaultValue=""><option value="" disabled>Select centre</option>{centres.map((centre) => <option key={centre.id} value={centre.id}>{centre.name} · {centre.code}</option>)}</select></label><label>Operation<select name="operation"><option>COLLECTION</option><option>RECEIVING</option><option>PACKING</option><option>TRANSPORT</option></select></label><label>Approved procedure reference<input name="reference" minLength={3} maxLength={200} required /></label><button className="button button-secondary" disabled={busy}>{busy ? "Saving…" : "Record approved reference"}</button><FormResult value={state} /></form> : <TableMessage value="No centre is available in your permission scope." />}</section>;
}

export function CollectionJobDetail({ id, staffId, grants = [] }: { id: string; staffId: string; grants?: readonly PermissionGrant[] }) {
  const [job, setJob] = useState<Job | null>(null); const [events, setEvents] = useState<Record<string, unknown>[]>([]); const [samples, setSamples] = useState<Specimen[]>([]); const [procedures, setProcedures] = useState<Procedure[]>([]); const [assignees, setAssignees] = useState<Assignee[]>([]); const [state, setState] = useState("Loading job…"); const [messageText, setMessageText] = useState(""); const [busy, setBusy] = useState(false);
  const actionAttempts = useRef(new Map<string, IdempotencyAttempt>());
  const refresh = useCallback(async () => { try { const r = await request(`/api/collections/${id}`); if (!r.response.ok) { setState(message(r.body, "Job unavailable.")); return; } const j = r.body.job as Job; setJob(j); setEvents((r.body.events ?? []) as Record<string, unknown>[]); setSamples((r.body.specimens ?? []) as Specimen[]); const p = await request("/api/samples/procedures"); setProcedures(p.response.ok ? (p.body.procedures ?? []) as Procedure[] : []); const a = await request(`/api/collections/assignees?centreId=${encodeURIComponent(j.centreId)}`); setAssignees(a.response.ok ? (a.body.assignees ?? []) as Assignee[] : []); setState(""); } catch { setState("Job service unavailable."); } }, [id]);
  useEffect(() => { void Promise.resolve().then(refresh); }, [refresh]);
  async function action(payload: Record<string, unknown>) { if (!job) return; setBusy(true); setMessageText(""); const actionName = typeof payload.action === "string" ? payload.action : "unknown"; const requestBody = JSON.stringify({ ...payload, expectedVersion: job.versionNumber }); const attemptId = `${job.id}:${actionName}`; const attempt = actionAttempts.current.get(attemptId) ?? new IdempotencyAttempt(actionName === "assign" ? `rudra:collection-assignment:${job.id}` : `rudra:collection-action:${attemptId}`); actionAttempts.current.set(attemptId, attempt); try { const idempotencyKey = await attempt.keyFor(requestBody); const { response, body } = await request(`/api/collections/${id}`, { method: "PATCH", headers: { "content-type": "application/json", "idempotency-key": idempotencyKey }, body: requestBody }); if (response.ok) { attempt.clear(); actionAttempts.current.delete(attemptId); setMessageText(body.replayed ? "The prior collection action was already saved." : "Collection workflow updated."); await refresh(); return; } if (response.status < 500) { attempt.clear(); actionAttempts.current.delete(attemptId); } setMessageText(`Action rejected: ${message(body, "service unavailable")}.`); } catch { setMessageText("Collection action could not be confirmed. Retry unchanged details to safely check whether it was saved."); } finally { setBusy(false); } }
  async function collect(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (busy) return;
    const formElement = event.currentTarget;
    const form = new FormData(formElement);
    const bodyData = { action: "collect", jobId: id, specimenType: String(form.get("specimenType")), requirementReference: String(form.get("requirementReference")), identityCheckConfirmed: form.get("identityCheckConfirmed") === "on", procedureApprovalId: String(form.get("procedureApprovalId")), reason: String(form.get("reason")) };
    const requestBody = JSON.stringify(bodyData);
    const { attemptId, attempt } = collectionSpecimenAttempt(id, actionAttempts.current);
    setBusy(true);
    setMessageText("");
    try {
      const idempotencyKey = await attempt.keyFor(requestBody);
      const { response, body } = await request("/api/samples", { method: "POST", headers: { "content-type": "application/json", "idempotency-key": idempotencyKey }, body: requestBody });
      if (response.ok) {
        attempt.clear();
        actionAttempts.current.delete(attemptId);
        setMessageText(`Specimen ${String((body.result as Record<string, unknown>)?.specimenNumber ?? "recorded")} recorded.`);
        formElement.reset();
        await refresh();
        return;
      }
      if (response.status < 500) {
        attempt.clear();
        actionAttempts.current.delete(attemptId);
        setMessageText(`Collection rejected: ${message(body, "service unavailable")}.`);
        return;
      }
      setMessageText("Collection save could not be confirmed. Retry unchanged details to safely check whether the specimen was saved.");
    } catch {
      setMessageText("Collection save could not be confirmed. Retry unchanged details to safely check whether the specimen was saved.");
    } finally {
      setBusy(false);
    }
  }
  if (state) return <section className="admin-card"><TableMessage value={state} /></section>; if (!job) return null;
  const canAssign = mayCreateCollectionJobAtCentre(grants, job.centreId); const canVisit = mayRecordVisitAtCentre(grants, job.centreId, job.assignedStaffId, staffId); const canCollect = mayCollectSampleAtCentre(grants, job.centreId, job.assignedStaffId, staffId);
  const latestAssignmentEvent = events.filter((event) => ["ASSIGNED", "REASSIGNED", "ASSIGNMENT_DECLINED", "ASSIGNMENT_ACCEPTED"].includes(String(event.eventType))).at(-1);
  const assignmentAccepted = latestAssignmentEvent?.eventType === "ASSIGNMENT_ACCEPTED";
  const collectionProcedures = procedures.filter((p) => p.centreId === job.centreId && p.operation === "COLLECTION");
  return <><section className="admin-card"><p className="eyebrow">{job.jobNumber} · {job.visitType}</p><h2>Job status: {job.status.replaceAll("_", " ")}</h2><p>Patient record: <code>{job.patientId}</code> · Order: <code>{job.orderId}</code> · Scheduled {new Date(job.scheduledStart).toLocaleString()}</p>{job.visitType === "HOME_COLLECTION" ? <p>Collection address: {job.homeCollectionAddress ? Object.values(job.homeCollectionAddress).join(", ") : "Not recorded"}. Window: {job.homeCollectionWindow ?? "Not recorded"}</p> : null}<FormResult value={messageText} />
    {canAssign && (["PENDING_ASSIGNMENT", "ASSIGNED", "UNSUCCESSFUL"].includes(job.status)) ? <form className="admin-form sample-form" onSubmit={(e) => { e.preventDefault(); const f = new FormData(e.currentTarget); void action({ action: "assign", staffUserId: String(f.get("staffUserId")), reason: String(f.get("reason")) }); }}><label>Authorized collector<select name="staffUserId" required defaultValue={job.assignedStaffId ?? ""}><option value="" disabled>Select active assigned collector</option>{assignees.map((a) => <option key={a.id} value={a.id}>{a.displayName} · {a.staffCode}</option>)}</select></label><label>Assignment reason<input name="reason" minLength={3} maxLength={240} required /></label><button className="button button-secondary" disabled={busy || !assignees.length}>{job.assignedStaffId ? "Reassign" : "Assign collector"}</button></form> : null}
    {canVisit && job.status === "ASSIGNED" ? <>{assignmentAccepted ? <><p role="status">Assignment accepted by the currently assigned collector.</p><button className="button button-primary" disabled={busy} onClick={() => void action({ action: "start", reason: "Assigned staff started the collection visit" })}>Start visit</button></> : <button className="button button-primary" disabled={busy} onClick={() => void action({ action: "accept", reason: "Assigned collector acknowledged the assignment" })}>Accept assignment</button>}<form className="admin-form sample-form" onSubmit={(e) => { e.preventDefault(); const f = new FormData(e.currentTarget); void action({ action: "decline", reason: String(f.get("reason")) }); }}><label>Decline assignment reason<input name="reason" required minLength={3} maxLength={240} placeholder="Brief operational reason" /></label><p>The job returns to the centre assignment queue. No patient notification is sent.</p><button className="button button-secondary" disabled={busy}>Decline assignment</button></form></> : null}
    {canVisit && job.status === "IN_PROGRESS" ? <div className="sample-action-row"><button className="button button-secondary" disabled={busy} onClick={() => void action({ action: "arrive", reason: "Arrival recorded by assigned staff" })}>Record arrival</button><form className="admin-form sample-form" onSubmit={(e) => { e.preventDefault(); const f = new FormData(e.currentTarget); const eta = String(f.get("estimatedArrivalAt") ?? ""); void action({ action: "delay", reason: String(f.get("reason")), ...(eta ? { estimatedArrivalAt: new Date(eta).toISOString() } : {}) }); }}><label>Record visit delay<input name="reason" required minLength={3} maxLength={240} placeholder="Brief operational reason" /></label><label>Estimated arrival (optional)<input name="estimatedArrivalAt" type="datetime-local" /></label><p>This is a staff estimate for internal coordination; it is not sent to the patient.</p><button className="button button-secondary" disabled={busy}>Record delay</button></form><form className="admin-form sample-form" onSubmit={(e) => { e.preventDefault(); const f = new FormData(e.currentTarget); void action({ action: "unsuccessful", reason: String(f.get("reason")) }); }}><label>Unsuccessful attempt reason<input name="reason" required minLength={3} maxLength={240}/></label><button className="button button-secondary" disabled={busy}>Mark attempt unsuccessful</button></form></div> : null}
    {canCollect && job.status === "IN_PROGRESS" ? <form className="admin-form sample-form" onSubmit={(e) => { e.preventDefault(); const f = new FormData(e.currentTarget); void action({ action: "complete", reason: String(f.get("reason")) }); }}><label>Visit completion confirmation<input name="reason" required minLength={3} maxLength={240} placeholder="Confirm the expected collection work was recorded" /></label><button className="button button-primary" disabled={busy || samples.length === 0}>{busy ? "Completing…" : "Complete collection visit"}</button><p>At least one specimen must be recorded. Completing this visit does not complete the diagnostic order.</p></form> : null}
    {canAssign && !(["CANCELLED", "COLLECTED"].includes(job.status)) ? <button className="text-button" disabled={busy} onClick={() => { const reason = window.prompt("Reason for cancelling this collection job:"); if (reason?.trim()) void action({ action: "cancel", reason: reason.trim() }); }}>Cancel job</button> : null}
  </section>
  {canCollect && job.status === "IN_PROGRESS" ? <section className="admin-card"><h2>Record a collected specimen</h2>{collectionProcedures.length ? <form className="admin-form sample-form" onSubmit={(e) => void collect(e)}><label>Specimen type<input name="specimenType" required minLength={2} maxLength={100} placeholder="Use approved order/procedure terminology" /></label><label>Verified requirement reference<input name="requirementReference" required minLength={3} maxLength={200} placeholder="Approved catalogue or procedure reference" /></label><label>Approved collection procedure<select name="procedureApprovalId" required defaultValue=""><option value="" disabled>Select approved reference</option>{collectionProcedures.map((p) => <option key={p.id} value={p.id}>{p.reference}</option>)}</select></label><label className="sample-check"><input type="checkbox" name="identityCheckConfirmed" required /> I confirm the locally approved identity-check step was completed.</label><label>Collection note / reason<input name="reason" required minLength={3} maxLength={240} /></label><button className="button button-primary" disabled={busy}>{busy ? "Recording…" : "Record specimen"}</button></form> : <p className="setup-notice">No active approved collection procedure reference exists for this centre. Collection recording remains blocked.</p>}</section> : null}
  <section className="admin-card"><h2>Specimens from this job</h2>{samples.length ? <div className="table-scroll"><table className="admin-table"><thead><tr><th>Rudra specimen ID</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody>{samples.map((sample) => <tr key={sample.id}><td>{sample.specimenNumber}</td><td>{sample.specimenType}</td><td>{sample.status.replaceAll("_", " ")}</td><td><Link href={`/samples/${sample.id}`}>Chain of custody</Link></td></tr>)}</tbody></table></div> : <TableMessage value="No specimens recorded." />}</section>
  <section className="admin-card"><h2>Collection visit history</h2><Timeline rows={events} /></section></>;
}

function Timeline({ rows }: { rows: Record<string, unknown>[] }) { return rows.length ? <ol className="sample-timeline">{rows.map((row, i) => <li key={`${String(row.recordedAt)}-${i}`}><strong>{String(row.eventType ?? "Event").replaceAll("_", " ")}</strong><span>{String(row.reason ?? "")}</span>{typeof row.estimatedArrivalAt === "string" ? <small>Staff-reported estimated arrival: {new Date(row.estimatedArrivalAt).toLocaleString()}</small> : null}<time>{row.recordedAt ? new Date(String(row.recordedAt)).toLocaleString() : ""}</time>{row.source ? <small>{String(row.source).replaceAll("_", " ")}</small> : null}</li>)}</ol> : <TableMessage value="No events recorded." />; }

function LinkedCollectionHistory({ id, endpoint, field, title }: { id: string; endpoint: string; field: "patientId" | "orderId" | "appointmentId"; title: string }) {
  const [jobs,setJobs]=useState<Job[]>([]); const [samples,setSamples]=useState<Specimen[]>([]); const [events,setEvents]=useState<Record<string,unknown>[]>([]); const [state,setState]=useState("Loading collection history…");
  const refresh=useCallback(async()=>{try{const {response,body}=await request(endpoint,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({[field]:id})});if(!response.ok){setState(message(body,"Collection history unavailable in this permission scope."));return;}const list=(body.jobs as Job[]|undefined)??(body.job?[body.job as Job]:[]);setJobs(list);setSamples((body.specimens??[]) as Specimen[]);const jobEvents=(body.jobEvents??[]) as Record<string,unknown>[];const custodyEvents=(body.custodyEvents??[]) as Record<string,unknown>[];setEvents([...jobEvents,...custodyEvents]);setState("");}catch{setState("Collection history is unavailable.");}},[endpoint,field,id]);
  useEffect(()=>{void Promise.resolve().then(refresh);},[refresh]);
  return <section className="admin-card"><h2>{title}</h2>{state?<TableMessage value={state}/>:jobs.length?<>{jobs.map((job)=><article className="sample-linked-job" key={job.id}><p><strong>{job.jobNumber}</strong> · {job.status.replaceAll("_"," ")} · {new Date(job.scheduledStart).toLocaleString()}</p><p><Link href={`/collections/${job.id}`}>Open collection workflow</Link></p></article>)}{samples.length?<div className="table-scroll"><table className="admin-table"><thead><tr><th>Specimen</th><th>Type</th><th>Status</th><th></th></tr></thead><tbody>{samples.map((sample)=><tr key={sample.id}><td>{sample.specimenNumber}</td><td>{sample.specimenType}</td><td>{sample.status.replaceAll("_"," ")}</td><td><Link href={`/samples/${sample.id}`}>Custody history</Link></td></tr>)}</tbody></table></div>:<TableMessage value="No specimen records have been entered."/>}<Timeline rows={events}/></>:<TableMessage value="No collection job is linked yet."/>}</section>;
}

export function PatientCollectionHistory({ patientId }: { patientId: string }) { return <LinkedCollectionHistory id={patientId} endpoint="/api/samples/patient-history" field="patientId" title="Collection & sample history" />; }
export function OrderCollectionHistory({ orderId }: { orderId: string }) { return <LinkedCollectionHistory id={orderId} endpoint="/api/samples/order-history" field="orderId" title="Collection & sample history" />; }
export function AppointmentCollectionHistory({ appointmentId }: { appointmentId: string }) { return <LinkedCollectionHistory id={appointmentId} endpoint="/api/samples/appointment-history" field="appointmentId" title="Collection & sample history" />; }

export function SamplesDirectory({ mode = "all", grants = [], initialCentreId, initialExceptionId }: { mode?: "all" | "receiving" | "handover" | "exceptions"; grants?: readonly PermissionGrant[]; initialCentreId?: string; initialExceptionId?: string }) {
  const [rows, setRows] = useState<Specimen[]>([]); const [procedures, setProcedures] = useState<Procedure[]>([]); const [state, setState] = useState("Loading sample records…"); const [result, setResult] = useState(""); const [busy, setBusy] = useState(""); const [page, setPage] = useState(1); const [hasMore, setHasMore] = useState(false);
  const handoverAttempts = useRef(new Map<string, IdempotencyAttempt>());
  const receiveAttempts = useRef(new Map<string, IdempotencyAttempt>());
  const refresh = useCallback(async () => { try { const params = new URLSearchParams({ view: mode === "all" ? "all" : mode, page: String(page), pageSize: "50" }); if (initialCentreId) params.set("centreId", initialCentreId); if (mode === "exceptions" && initialExceptionId) params.set("exceptionId", initialExceptionId); const [s,p] = await Promise.all([request(`/api/samples?${params}`), request("/api/samples/procedures")]); if (!s.response.ok) { setState(message(s.body, "Sample service unavailable.")); return; } setRows((s.body.specimens ?? []) as Specimen[]); setHasMore(s.body.hasMore === true); setProcedures(p.response.ok ? (p.body.procedures ?? []) as Procedure[] : []); setState(""); } catch { setRows([]); setHasMore(false); setState("Sample service unavailable."); } }, [initialCentreId, initialExceptionId, mode, page]);
  useEffect(() => { void Promise.resolve().then(refresh); }, [refresh]);
  async function submitHandover(sample: Specimen) {
    const payload = { action: "submit_for_receiving", specimenId: sample.id, expectedVersion: sample.versionNumber, reason: "Submitted to Rudra receiving queue" };
    const requestBody = JSON.stringify(payload);
    const attempt = handoverAttempts.current.get(sample.id) ?? new IdempotencyAttempt(`rudra:sample-handover:${sample.id}`);
    handoverAttempts.current.set(sample.id, attempt);
    setBusy(sample.id); setResult("");
    try {
      const idempotencyKey = await attempt.keyFor(requestBody);
      const { response, body } = await request("/api/samples", { method: "POST", headers: { "content-type": "application/json", "idempotency-key": idempotencyKey }, body: requestBody });
      if (response.ok) { attempt.clear(); handoverAttempts.current.delete(sample.id); setResult(`${sample.specimenNumber} submitted to Rudra receiving. Physical receipt still requires a separate receiving action.`); await refresh(); }
      else { if (response.status < 500) { attempt.clear(); handoverAttempts.current.delete(sample.id); } setResult(`Submission rejected: ${message(body, "service unavailable")}.`); }
    } catch { setResult("Submission could not be confirmed. Retry without changing the request to safely check whether it was saved."); }
    finally { setBusy(""); }
  }
  async function receive(sample: Specimen, procedureApprovalId: string) {
    const payload = { action: "receive", specimenId: sample.id, expectedVersion: sample.versionNumber, procedureApprovalId, reason: "Specimen matched against the receiving record" };
    const requestBody = JSON.stringify(payload);
    const attempt = receiveAttempts.current.get(sample.id) ?? new IdempotencyAttempt(`rudra:sample-receive:${sample.id}`);
    receiveAttempts.current.set(sample.id, attempt); setBusy(sample.id); setResult("");
    try {
      const idempotencyKey = await attempt.keyFor(requestBody);
      const { response, body } = await request("/api/samples", { method: "POST", headers: { "content-type": "application/json", "idempotency-key": idempotencyKey }, body: requestBody });
      if (response.ok) { attempt.clear(); receiveAttempts.current.delete(sample.id); setResult(body.result && typeof body.result === "object" && "replayed" in body.result && body.result.replayed === true ? `${sample.specimenNumber} was already received at Rudra.` : `${sample.specimenNumber} received at Rudra.`); await refresh(); }
      else { if (response.status < 500) { attempt.clear(); receiveAttempts.current.delete(sample.id); } setResult(`Receive rejected: ${message(body, "service unavailable")}.`); }
    } catch { setResult("Receipt could not be confirmed. Retry unchanged details to safely check whether it was saved."); }
    finally { setBusy(""); }
  }
  async function createException(event: React.FormEvent<HTMLFormElement>, sample: Specimen) { event.preventDefault(); const form = new FormData(event.currentTarget); setBusy(sample.id); const { response, body } = await request("/api/samples", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action: "exception", specimenId: sample.id, type: String(form.get("type")), reason: String(form.get("reason")) }) }); setResult(response.ok ? `Exception recorded for ${sample.specimenNumber}.` : `Exception rejected: ${message(body, "service unavailable")}.`); setBusy(""); if (response.ok) await refresh(); }
  const shown = rows;
  return <><section className="admin-card">{mode === "handover" ? <p className="setup-notice">Submit your collected specimens to the Rudra receiving queue. Submission records a handover request only; receiving staff must separately confirm physical receipt.</p> : null}{mode === "exceptions" && initialExceptionId ? <p className="setup-notice">Showing the specimen linked to this escalation. Open its history to review authorized exception events and current status.</p> : null}<FormResult value={result} />{state ? <TableMessage value={state} /> : shown.length ? <div className="table-scroll"><table className="admin-table"><thead><tr><th>Specimen</th><th>Patient</th><th>Type / requirement</th><th>Status</th><th>Handover status</th><th>Recorded</th><th>Action</th></tr></thead><tbody>{shown.map((sample) => { const receiving = procedures.find((p) => p.centreId === sample.centreId && p.operation === "RECEIVING"); const canReadThisSample = grants.some((grant) => grant.key === "samples.read" && (grant.centreId === null || grant.centreId === sample.centreId)); return <tr key={sample.id}><td>{canReadThisSample ? <Link href={`/samples/${sample.id}`}>{sample.specimenNumber}</Link> : sample.specimenNumber}</td><td>{sample.patientName || "Assigned patient"} {sample.patientLastName ?? ""}</td><td>{canReadThisSample ? <>{sample.specimenType}<small>{sample.requirementReference}</small></> : "Collected specimen"}</td><td>{sample.status.replaceAll("_", " ")}</td><td>{sample.handoverSubmitted ? "Submitted; awaiting physical receipt" : sample.receivingSubmissionRequired ? "Awaiting collector submission" : "Legacy record"}</td><td>{new Date(sample.collectedAt).toLocaleString()}</td><td>{mode === "handover" && sample.canSubmitHandover && sample.status === "COLLECTED" && !sample.handoverSubmitted ? <button className="text-button" disabled={busy === sample.id} onClick={() => void submitHandover(sample)}>Submit to Rudra receiving</button> : mode === "receiving" && sample.status === "COLLECTED" && mayReceiveSamplesAtCentre(grants, sample.centreId) ? <button className="text-button" disabled={busy === sample.id || !receiving || (sample.receivingSubmissionRequired === true && !sample.handoverSubmitted)} onClick={() => receiving && void receive(sample, receiving.id)}>{!receiving ? "Receiving procedure required" : sample.receivingSubmissionRequired && !sample.handoverSubmitted ? "Awaiting collector submission" : "Receive at Rudra"}</button> : canReadThisSample ? <Link href={`/samples/${sample.id}`}>View history</Link> : <span>Awaiting permitted action</span>}</td></tr>; })}</tbody></table></div> : <TableMessage value={initialExceptionId ? "The linked sample exception is unavailable in this centre or permission scope." : mode === "receiving" || mode === "handover" ? "No collected specimens are waiting for Rudra receiving." : mode === "exceptions" ? "No open sample exceptions." : "No specimen records."} />}</section>{page > 1 || hasMore ? <div className="admin-card action-row"><button className="button button-secondary" disabled={page <= 1} onClick={() => setPage((current) => current - 1)}>Previous page</button><span>Page {page}</span><button className="button button-secondary" disabled={!hasMore} onClick={() => setPage((current) => current + 1)}>Next page</button></div> : null}{shown.some((sample) => mayManageSampleExceptionsAtCentre(grants, sample.centreId)) && mode !== "receiving" && mode !== "handover" ? <section className="sample-card-grid">{shown.filter((sample) => mayManageSampleExceptionsAtCentre(grants, sample.centreId) && !["DISPATCHED", "EXTERNAL_RECEIPT_RECORDED", "EXCEPTION", "RECOLLECTION_REQUIRED"].includes(sample.status)).map((sample) => <form className="admin-card" key={sample.id} onSubmit={(e) => void createException(e, sample)}><h2>Record exception · {sample.specimenNumber}</h2><label>Type<select name="type"><option>MISSING_LABEL</option><option>DAMAGED</option><option>MISSING_SPECIMEN</option><option>HANDOVER_DISCREPANCY</option><option>REJECTED</option><option>OTHER</option></select></label><label>Operational reason<input name="reason" minLength={3} maxLength={240} required /></label><button className="button button-secondary" disabled={busy === sample.id}>Record exception</button></form>)}</section> : null}</>;
}

export function SpecimenDetail({ id, grants = [] }: { id: string; grants?: readonly PermissionGrant[] }) {
  const [specimen, setSpecimen] = useState<Specimen | null>(null); const [events, setEvents] = useState<Record<string, unknown>[]>([]); const [exceptions, setExceptions] = useState<Record<string, unknown>[]>([]); const [procedures, setProcedures] = useState<Procedure[]>([]); const [state, setState] = useState("Loading sample history…"); const [result, setResult] = useState("");
  const refresh = useCallback(async () => { const [s,p] = await Promise.all([request(`/api/samples/${id}`), request("/api/samples/procedures")]); if (!s.response.ok) { setState(message(s.body, "Sample unavailable.")); return; } const d = s.body; setSpecimen(d.specimen as Specimen); setEvents((d.events ?? []) as Record<string, unknown>[]); setExceptions((d.exceptions ?? []) as Record<string, unknown>[]); setProcedures(p.response.ok ? (p.body.procedures ?? []) as Procedure[] : []); setState(""); }, [id]);
  useEffect(() => { void Promise.resolve().then(refresh); }, [refresh]);
  async function submit(event: React.FormEvent<HTMLFormElement>, action: string, exceptionId: string) { event.preventDefault(); const form = new FormData(event.currentTarget); const { response, body } = await request(`/api/samples/${id}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ action, exceptionId, reason: String(form.get("reason")), resolutionReference: String(form.get("resolutionReference") ?? "") || undefined }) }); setResult(response.ok ? "Exception update recorded." : `Update rejected: ${message(body, "service unavailable")}.`); if (response.ok) await refresh(); }
  if (state) return <section className="admin-card"><TableMessage value={state} /></section>; if (!specimen) return null;
  const issue = exceptions.find((item) => item.status === "OPEN"); const canRecollect = procedures.some((p) => p.centreId === specimen.centreId && p.operation === "COLLECTION"); const canAuthorizeRecollection = mayAuthorizeRecollectionAtCentre(grants, specimen.centreId); const canManageExceptions = mayManageSampleExceptionsAtCentre(grants, specimen.centreId);
  return <><section className="admin-card"><p className="eyebrow">{specimen.specimenNumber}</p><h2>{specimen.specimenType} · {specimen.status.replaceAll("_", " ")}</h2><p>Requirement reference: {specimen.requirementReference}</p><p>Order <code>{specimen.orderId}</code> · Collection job <Link href={`/collections/${specimen.jobId}`}>{specimen.jobId}</Link></p><p>Identity check recorded: {specimen.identityCheckConfirmed ? "Yes" : "No"}. Collected {new Date(specimen.collectedAt).toLocaleString()}.</p><FormResult value={result} /></section>
    <section className="admin-card"><h2>Chain of custody</h2><Timeline rows={events} /></section>
    {issue ? <section className="admin-card"><h2>Open exception · {String(issue.type).replaceAll("_", " ")}</h2><p>{String(issue.reason)}</p><div className="sample-action-row">{canAuthorizeRecollection ? canRecollect ? <form className="admin-form" onSubmit={(e) => void submit(e, "request_recollection", String(issue.id))}><label>Recollection authorization reason<input name="reason" required minLength={3} maxLength={240} /></label><button className="button button-secondary">Request recollection</button></form> : <p className="setup-notice">An approved collection procedure reference is required before recollection can be requested.</p> : null}{canManageExceptions ? <form className="admin-form" onSubmit={(e) => void submit(e, "resolve", String(issue.id))}><label>Resolution evidence reference<input name="resolutionReference" required minLength={3} maxLength={200} /></label><label>Resolution reason<input name="reason" required minLength={3} maxLength={240} /></label><button className="button button-secondary">Resolve exception</button></form> : null}</div></section> : null}
  </>;
}

export function DispatchDesk({ grants = [], initialCentreId }: { grants?: readonly PermissionGrant[]; initialCentreId?: string }) {
  const [samples,setSamples]=useState<Specimen[]>([]); const [procedures,setProcedures]=useState<Procedure[]>([]); const [batches,setBatches]=useState<Batch[]>([]); const [selected,setSelected]=useState<string[]>([]); const [centreId,setCentreId]=useState(initialCentreId??""); const [state,setState]=useState("Loading dispatch queue…"); const [result,setResult]=useState(""); const [busy,setBusy]=useState(false); const [page,setPage]=useState(1); const [hasMore,setHasMore]=useState(false); const [batchPage,setBatchPage]=useState(1); const [hasMoreBatches,setHasMoreBatches]=useState(false);
  const refresh=useCallback(async()=>{const sampleParams=new URLSearchParams({view:"all",page:String(page),pageSize:"50"});const batchParams=new URLSearchParams({page:String(batchPage),pageSize:"25"});if(centreId){sampleParams.set("centreId",centreId);batchParams.set("centreId",centreId);}const [s,p,b]=await Promise.all([request(`/api/samples?${sampleParams}`),request("/api/samples/procedures"),request(`/api/samples/dispatch?${batchParams}`)]);if(!s.response.ok){setState(message(s.body,"Dispatch queue unavailable."));return;}const sampleRows=(s.body.specimens??[]) as Specimen[];setSamples(sampleRows);setHasMore(s.body.hasMore===true);setProcedures(p.response.ok?(p.body.procedures??[]) as Procedure[]:[]);setBatches(b.response.ok?(b.body.batches??[]) as Batch[]:[]);setHasMoreBatches(b.response.ok && b.body.hasMore===true);setState("");},[page,batchPage,centreId]);
  useEffect(()=>{void Promise.resolve().then(refresh);},[refresh]);
  const available=samples.filter((s)=>s.status==="RECEIVED_AT_RUDRA" && mayDispatchSamplesAtCentre(grants,s.centreId)); const centreOptions=Array.from(new Map(available.map((s)=>[s.centreId,{id:s.centreId,name:s.centreId}])).values()); const filtered=available.filter((s)=>!centreId||s.centreId===centreId); const packing=procedures.find((p)=>p.centreId===centreId&&p.operation==="PACKING");
  async function create(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(!packing||!selected.length)return;setBusy(true);const {response,body}=await request("/api/samples/dispatch",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({centreId,specimenIds:selected,packingProcedureApprovalId:packing.id,reason:"Rudra receiving reconciliation complete; batch prepared"})});setResult(response.ok?`Dispatch batch ${String((body.batch as Record<string,unknown>)?.batchNumber)} created.`:`Batch rejected: ${message(body,"service unavailable")}.`);setBusy(false);if(response.ok){setSelected([]);await refresh();}}
  return <><section className="admin-card"><h2>Specimens ready for packing</h2>{state?<TableMessage value={state}/>:null}<label>Centre<select value={centreId} onChange={(e)=>{setCentreId(e.target.value);setSelected([]);}}><option value="">Select centre</option>{centreOptions.map((c)=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><FormResult value={result}/>{filtered.length?<form onSubmit={(e)=>void create(e)}><div className="table-scroll"><table className="admin-table"><thead><tr><th>Select</th><th>Specimen</th><th>Type</th><th>Patient ID</th></tr></thead><tbody>{filtered.map((s)=><tr key={s.id}><td><input type="checkbox" checked={selected.includes(s.id)} onChange={(e)=>setSelected((prev)=>e.target.checked?[...prev,s.id]:prev.filter((id)=>id!==s.id))}/></td><td><Link href={`/samples/${s.id}`}>{s.specimenNumber}</Link></td><td>{s.specimenType}</td><td><code>{s.patientId}</code></td></tr>)}</tbody></table></div><p>Only samples recorded as received at Rudra can be packed.</p><button className="button button-primary" disabled={busy||!selected.length||!packing}>{busy?"Creating batch…":packing?"Create dispatch batch":"Approved packing procedure required"}</button></form>:<TableMessage value="No specimens are ready for packing on this page."/>}<div className="action-row"><button className="button button-secondary" disabled={page<=1} onClick={()=>{setSelected([]);setPage((current)=>current-1);}}>Previous page</button><span>Page {page}</span><button className="button button-secondary" disabled={!hasMore} onClick={()=>{setSelected([]);setPage((current)=>current+1);}}>Next page</button></div></section>
    <section className="admin-card"><h2>Dispatch register</h2>{batches.length?<div className="table-scroll"><table className="admin-table"><thead><tr><th>Batch</th><th>Status</th><th>Carrier</th><th></th></tr></thead><tbody>{batches.map((b)=><tr key={b.id}><td>{b.batchNumber}</td><td>{b.status.replaceAll("_"," ")}</td><td>{b.carrierReference??"Awaiting handover"}</td><td><Link href={`/samples/dispatch/${b.id}`}>Open batch</Link></td></tr>)}</tbody></table></div>:<TableMessage value="No dispatch batches recorded."/>}<div className="action-row"><button className="button button-secondary" disabled={batchPage<=1} onClick={()=>setBatchPage((current)=>current-1)}>Previous page</button><span>Page {batchPage}</span><button className="button button-secondary" disabled={!hasMoreBatches} onClick={()=>setBatchPage((current)=>current+1)}>Next page</button></div></section></>;
}

export function DispatchBatchDetail({ id, grants = [] }: { id: string; grants?: readonly PermissionGrant[] }) {
  const [batch,setBatch]=useState<Batch|null>(null); const [items,setItems]=useState<Record<string,unknown>[]>([]); const [procedures,setProcedures]=useState<Procedure[]>([]); const [state,setState]=useState("Loading batch…"); const [result,setResult]=useState(""); const [busy,setBusy]=useState(false);
  const refresh=useCallback(async()=>{const [b,p]=await Promise.all([request(`/api/samples/dispatch/${id}`),request("/api/samples/procedures")]);if(!b.response.ok){setState(message(b.body,"Batch unavailable."));return;}setBatch(b.body.batch as Batch);setItems((b.body.items??[]) as Record<string,unknown>[]);setProcedures(p.response.ok?(p.body.procedures??[]) as Procedure[]:[]);setState("");},[id]);useEffect(()=>{void Promise.resolve().then(refresh);},[refresh]);
  async function submit(event:React.FormEvent<HTMLFormElement>,action:string){event.preventDefault();if(!batch)return;const form=new FormData(event.currentTarget);setBusy(true);const payload=action==="handover"?{action,batchId:id,expectedVersion:batch.versionNumber,carrierReference:String(form.get("carrierReference")),externalLabReference:String(form.get("externalLabReference"))||undefined,procedureApprovalId:String(form.get("procedureApprovalId")),reason:String(form.get("reason"))}:{action,batchId:id,receiptReference:String(form.get("receiptReference")),evidenceReference:String(form.get("evidenceReference")),reason:String(form.get("reason"))};const {response,body}=await request(`/api/samples/dispatch/${id}`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});setResult(response.ok?action==="handover"?"Carrier handover recorded.":"Manually reviewed external receipt evidence recorded.":`Action rejected: ${message(body,"service unavailable")}.`);setBusy(false);if(response.ok)await refresh();}
  if(state)return <section className="admin-card"><TableMessage value={state}/></section>;if(!batch)return null;
  const transport=procedures.find((p)=>p.centreId===batch.centreId&&p.operation==="TRANSPORT");
  const canDispatch = mayDispatchSamplesAtCentre(grants, batch.centreId); const canVerifyExternal = mayVerifyExternalReceiptAtCentre(grants, batch.centreId);
  return <><section className="admin-card"><p className="eyebrow">{batch.batchNumber}</p><h2>Status: {batch.status.replaceAll("_"," ")}</h2><FormResult value={result}/><h3>Included specimens</h3><ul>{items.map((item)=><li key={String(item.id)}>{String(item.specimenNumber)} · {String(item.specimenType)}</li>)}</ul></section>{canDispatch && batch.status==="PREPARING"?<section className="admin-card"><h2>Record custody handover</h2>{transport?<form className="admin-form sample-form" onSubmit={(e)=>void submit(e,"handover")}><label>Carrier / authorized receiver reference<input name="carrierReference" required minLength={2} maxLength={200}/></label><label>External lab reference, if supplied<input name="externalLabReference" maxLength={200}/></label><label>Approved transport procedure<select name="procedureApprovalId" required defaultValue=""><option value="" disabled>Select approved reference</option>{procedures.filter((p)=>p.centreId===batch.centreId&&p.operation==="TRANSPORT").map((p)=><option key={p.id} value={p.id}>{p.reference}</option>)}</select></label><label>Handover note<input name="reason" required minLength={3} maxLength={240}/></label><button className="button button-primary" disabled={busy}>Record dispatch handover</button></form>:<p className="setup-notice">Approved transport procedure reference required.</p>}</section>:null}{canVerifyExternal && batch.status==="DISPATCHED"?<section className="admin-card"><h2>Record reviewed laboratory receipt</h2><p>This is a manual record of external evidence. No laboratory API or automatic acknowledgement is connected.</p><form className="admin-form sample-form" onSubmit={(e)=>void submit(e,"receipt")}><label>Receipt reference supplied externally<input name="receiptReference" required minLength={2} maxLength={200}/></label><label>Evidence reference (document/control reference, no patient data)<input name="evidenceReference" required minLength={3} maxLength={200}/></label><label>Review note<input name="reason" required minLength={3} maxLength={240}/></label><button className="button button-primary" disabled={busy}>Record manually verified receipt</button></form></section>:null}</>;
}

export function FieldAssignments() { return <CollectionOperations />; }
